import 'fake-indexeddb/auto';
import Dexie from 'dexie';
import {it,expect,afterEach,vi} from 'vitest';
import {readFileSync,writeFileSync} from 'node:fs';
import {newId} from '../src/domain/model';
import {ScopedEditorStore,type EditorImage,type EditorWork} from '../src/sync/editorStore';
import {valueHash,type SyncAck} from '../src/sync/protocol';
import {threeWayMerge} from '../src/sync/merge';
const root='/tmp/shinariokanri-independent-rb09-af0c2b9/independent',stores:ScopedEditorStore[]=[];
afterEach(async()=>{vi.restoreAllMocks();for(const s of stores.splice(0))await s.delete();});
function proof(id:string,data:unknown){writeFileSync(`${root}/fixtures/${id}.json`,JSON.stringify(data,null,2)+'\n');}
function fixed(){const initial=JSON.parse(readFileSync(`${root}/fixed-fixtures/R9E00.json`,'utf8')).initial;return initial.base as EditorImage;}
async function image(revision='1',expiresAt:string|null=null){return {...fixed(),authorizationRevision:revision,authorizationExpiresAt:expiresAt};}
async function seed(expiresAt:string|null=null){const s=new ScopedEditorStore(newId());stores.push(s);const x=await image('1',expiresAt);await s.receive(x);return {s,x,id:x.documents[0].id};}
async function staleGrant(){const f=await seed(),project=f.x.projectId;await f.s.saveField(project,f.id,'name','独立端末A');const op=(await f.s.prepare(project))!,server=f.x.documents.map(d=>({...structuredClone(d),revision:'2',fields:{...d.fields,name:d.id===f.id?'確認済み遠隔A2':'確認済み遠隔B2'}})),common=op.targets[0].base!,merged=threeWayMerge(common,op.targets[0].local,server.find(d=>d.id===f.id)!);if(merged.status!=='conflict')throw Error('REVIEW_EXPECTED_CONFLICT');await f.s.acknowledge({schemaVersion:1,operationId:op.operationId,scope:op.scope,operationHash:await valueHash(op),status:'conflict',serverRevision:'2',authorizationRevision:'1',authorizationExpiresAt:null,documents:[server.find(d=>d.id===f.id)!],confirmedDocuments:server,conflicts:[merged.conflict]});return {...f,project,op,server,original:(await f.s.get(project))!};}
async function addedGrant(){const f=await staleGrant(),c={...structuredClone(f.x.documents[0]),id:newId(),fields:{...f.x.documents[0].fields,name:'古い版だけの新規C'}};const stale={...structuredClone(f.x),authorizationRevision:'2',documents:[{...structuredClone(f.x.documents[0]),fields:{...f.x.documents[0].fields,'data.body':[{id:newId(),kind:'paragraph',text:'未検証の古い本文😀'}]}},c]};stale.contentHash=await valueHash(stale.documents);return {...f,c,stale};}
it('R9C8MASK01 new-authority/old-content grant keeps confirmed remote A2; added body/C are unusable until fresh current image, then only observed grant fields become usable',async()=>{
 const f=await addedGrant();await f.s.receive(f.stale);const masked=(await f.s.get(f.project))!;expect(masked.base.serverRevision).toBe('2');expect(masked.documents[0].fields.name).toBe('確認済み遠隔A2');expect(masked.documents[0].fields).not.toHaveProperty('data.body');expect(masked.documents.map(d=>d.id)).not.toContain(f.c.id);expect(masked.permissionObservation).toEqual(f.stale);expect(masked.recovered).toContainEqual(f.original);await expect(f.s.saveField(f.project,f.id,'data.body',[])).rejects.toMatchObject({code:'FORBIDDEN'});await expect(f.s.saveField(f.project,f.c.id,'name','未知Cを昇格')).rejects.toMatchObject({code:'FORBIDDEN'});expect(await f.s.get(f.project)).toEqual(masked);
 const fresh={...structuredClone(f.stale),serverRevision:'2',documents:[{...structuredClone(masked.documents[0]),fields:{...masked.documents[0].fields,'data.body':[{id:newId(),kind:'paragraph',text:'検証済み現在本文😀'}]}},{...structuredClone(f.c),revision:'2',fields:{...f.c.fields,name:'検証済み現在C'}}]};fresh.contentHash=await valueHash(fresh.documents);await f.s.receive(fresh);const current=(await f.s.get(f.project))!;expect(current.documents).toEqual(fresh.documents);await f.s.saveField(f.project,f.c.id,'name','現行Cの正常編集');const after=(await f.s.get(f.project))!;expect(after.documents.find(d=>d.id===f.c.id)!.fields.name).toBe('現行Cの正常編集');expect(after.recovered).toContainEqual(f.original);proof('R9C8MASK01',{original:f.original,stale:f.stale,masked,fresh,current,after});
});
it('R9C8MASK02 current content cannot widen newly observed field mask with an extra undeclared C body; all prior state/evidence unchanged',async()=>{
 const f=await addedGrant();await f.s.receive(f.stale);const before=(await f.s.get(f.project))!,forged={...structuredClone(f.stale),serverRevision:'2',documents:[before.documents[0],{...structuredClone(f.c),revision:'2',fields:{...f.c.fields,'data.body':[{id:newId(),kind:'paragraph',text:'許可宣言に無いC本文'}]}}]};forged.contentHash=await valueHash(forged.documents);await expect(f.s.receive(forged)).rejects.toMatchObject({code:'REVISION_CHANGED'});const after=await f.s.get(f.project);expect(after).toEqual(before);proof('R9C8MASK02',{stale:f.stale,before,forged,after});
});
it('R9C8MASK03 cold cache preserves source grant observation/full old work but never promotes unseen body/C; grant expiry stops even currently confirmed A atomically',async()=>{
 const f=await addedGrant(),deadline=Date.now()+60000;f.stale.authorizationExpiresAt=new Date(deadline).toISOString();await f.s.receive(f.stale);const before=(await f.s.get(f.project))!;f.s.close();stores.splice(stores.indexOf(f.s),1);const reopened=new ScopedEditorStore(f.s.accountId);stores.push(reopened);expect(await reopened.get(f.project)).toEqual(before);await expect(reopened.saveField(f.project,f.c.id,'name','cold未知C')).rejects.toMatchObject({code:'FORBIDDEN'});vi.spyOn(Date,'now').mockReturnValue(deadline+1);await expect(reopened.saveField(f.project,f.id,'name','期限後A')).rejects.toMatchObject({code:'FORBIDDEN'});const after=await reopened.get(f.project);expect(after).toEqual(before);proof('R9C8MASK03',{before,after,stale:f.stale});
});
it('R9C8MASK04 explicit recovery adopts edited A only; untouched common B never overwrites confirmed remote B2 and new prepared operation includes A only',async()=>{
 const f=await staleGrant(),stale={...structuredClone(f.x),authorizationRevision:'2'};await f.s.receive(stale);const before=(await f.s.get(f.project))!;expect(before.documents.find(d=>d.id===f.x.documents[1].id)!.fields.name).toBe('確認済み遠隔B2');const plan=await f.s.previewRecovery(f.project,before.recovered!.length-1);expect(plan.documents.find(d=>d.id===f.id)!.fields.name).toBe('独立端末A');expect(plan.documents.find(d=>d.id===f.x.documents[1].id)!.fields.name).toBe('確認済み遠隔B2');await f.s.adoptRecovery(plan);const after=(await f.s.get(f.project))!,operation=(await f.s.prepare(f.project))!;expect(after.documents.find(d=>d.id===f.x.documents[1].id)!.fields.name).toBe('確認済み遠隔B2');expect(after.recovered).toContainEqual(f.original);expect(operation.targets.map(t=>t.targetId)).toEqual([f.id]);expect(operation.baseRevision).toBe('2');expect(operation.operationId).not.toBe(f.op.operationId);proof('R9C8MASK04',{original:f.original,stale,before,plan,after,operation});
});
